import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();
        int[] a = new int[n];
        int count = 0;

        for (int i = 0; i < n; i++) {
            a[i] = scanner.nextInt();
            count += a[i];
        }

        int temp = a[0];
        if (n > 1) {
            for (int i = 0; i < n; i++) {
                temp = Math.max(temp, a[i]);
            }
        }

        int ans = 0;
        for (int i = 0; ; i++) {
            int k = temp + i;
            if ((n * k) - count > count) {
                ans = k;
                break;
            }
        }

        System.out.print(ans);
        scanner.close();
    }
}

